import json, pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
ROWS=[]
def add(row,status,boundary,proposition,surfaces,hidden,reason,repair='',sources=()):
    ROWS.append(dict(rowKey=row,disposition=status,proposedBoundary=boundary,answerProposition=proposition,establishingSurfaces=surfaces,laterInformationToHide=hidden,boundaryDefense=reason,requiredContentWork=repair,sourceIds=list(sources),authority='Fresh producer proposal; independent clinical/bilingual and boundary review required',deterministic=False))
A='ANCHOR_ONLY_REPAIR_CANDIDATE'; C='CONTENT_REPAIR_REQUIRED'; R='REPLACEMENT_CANDIDATE'; H='REVIEW_HOLD'
add('25b7ff4311e66f43',C,'stage_pod3','Discharge handoff must communicate the actual postoperative course, LEP communication needs, medication teaching, follow-up and renal recovery, including keyed F.', 'Baseline history; POD1/POD2 course; POD3 renal recovery and confirmed discharge arrangements.', 'POD3 completed SBAR enumeration currently supplies the selected handoff contents; no subsequent stage exists.', 'Baseline cannot establish the later recovery/confirmed follow-up; the necessary POD3 prefix must first cease spelling out the answer.', 'Revise bilingual POD3 exhibit to retain factual readiness/contact/appointment/renal data while removing the completed-SBAR answer enumeration. Preserve q6 options/key pending independent review.')
add('f9ac2b9add5ea7c9',C,'stage_3','After the client reaffirms wishes, verify/document the code-status order, communicate with the authorized contact, and report the earlier delay.', 'Baseline expressly lacks an appointed proxy; stage_1/stage_2 show delay; stage_3 records completed orders and an advance directive with daughter present.', 'No later stage. The mere completion of an advance directive must not be treated as appointment of the daughter as proxy.', 'Stage_3 establishes completed documentation but cannot repair the unsupported proxy premise in option C.', 'Replace healthcare-proxy assumption in option C and corresponding rationale with communication to the client-designated daughter/contact after permission; explicitly distinguish emergency contact from decision-making authority.',('advance-directives','hipaa-family'))
add('069feba96b2b8325',C,None,'Identify a newly added thiazide as a contributor to lithium accumulation in a dehydrated patient with impaired renal clearance.', 'Admission data contain renal impairment/dehydration and lithium 2.8, but no thiazide medication chronology. Stage_1 names holding HCTZ and a new blood-pressure pill.', 'Stage_1 treatment decision to stop HCTZ and stage_2 dialysis explanation should not substitute for a pretreatment medication history.', 'The admission-time causal question requires a history absent at admission; rationale also invents years of therapeutic stability.', 'Add an explicitly authored, reviewer-approved pretreatment medication reconciliation with drug/start chronology to baseline, or rewrite the causal question and remove unsupported chronic stability claims. Reassess baseline only after that choice.',('lithium-label',))
add('e16efeb234f31534',A,'baseline','Vomiting with deteriorating consciousness creates an immediate airway/aspiration priority; position laterally and prepare suction.', 'Part stem explicitly supplies vomiting, declining consciousness and instability; baseline establishes lithium toxicity and depressed consciousness.', 'stage_1 performed lateral positioning/suction; stage_2 dialysis and stage_3 recovery.', 'The decision inputs are in the stem; actual later chart execution supplies the action rather than a missing determinant. No later numerical result is needed.',sources=('aspiration',))
add('117e92a832582184',A,'baseline','Among the fully specified offered indications, neurologic toxicity with impaired elimination/persistent toxicity is the strongest justification for recommended extracorporeal treatment.', 'Stem states a dialysis recommendation; answer options supply the candidate indication combinations; baseline confirms severe lithium poisoning.', 'stage_2 nephrologist explicitly recites the selected indication triad; stage_3 post-dialysis response.', 'This asks which offered indication most strongly justifies an already stated recommendation, not which new laboratory value occurred. Decreased consciousness is itself a recognized indication; reviewer must confirm this reading in both languages.',sources=('extrip',))
add('6a1c2b0d2f2252a6',C,None,'Compare the prescribed potassium concentration/rate against an explicitly applicable peripheral-infusion protocol and query a nonconforming order.', 'q4 order 20 mEq/100 mL over one hour; Chinese duration means longer than one hour; rationale asserts an unsupplied universal peripheral limit.', 'stage_2 order/response and stage_3 outcomes cannot resolve the absent protocol or translation.', 'No existing anchor makes conflicting durations and an unspecified concentration ceiling determinate.', 'Harmonize English/Chinese duration in stem and matching exhibit; provide a sourced product/facility-specific limit as case context, revise rationale against it, then use baseline if the stem is self-contained. Do not invent a universal 10 mEq/100 mL ceiling.',('kcl-label',))
add('a47ec00ef1455a0c',C,'stage_adherence_issue','Recognize excessive lactulose-associated watery diarrhea and seek dose adjustment while monitoring fluid/electrolyte losses.', 'stage_adherence_issue provides 5–6 watery stools daily for three days, cramps, wish to stop, and no new confusion; baseline medications.', 'No later stage; keep the symptom report without adding an explicit clinician answer.', 'Actual stool burden is absent at baseline and needed; anchor cannot repair the erroneous spironolactone explanation or absolute no-stopping rule.', 'Correct rationale/strategy: spironolactone retains potassium, not a cause of worsening potassium loss by its usual mechanism; remove blanket never-stop claim and align excessive-diarrhea management with prescribed plan/label.',('lactulose-label','spironolactone-label'))
add('7fe104dccf843914',R,None,'Select safe symptom-directed low-dose opioid care for refractory dyspnea with reassessment for benefit and adverse effects.', 'Baseline end-stage heart failure, severe dyspnea and comfort goals; current cloze distractors include both CO2 and low-O2 responses while rationale endorses both.', 'stage_hospice_followup easier breathing after morphine and somnolence would give the treatment response.', 'A different anchor cannot make two rationale-supported mechanisms an exclusive cloze choice.', 'Replace this embedded part in place with a clinically sourced symptom-management/monitoring construct and a natural answer structure. Preserve parent/part identity pending replacement plan review; avoid overclaiming oral morphine venodilation or absence of respiratory risk.',('morphine-label','palliative-dyspnea'))
add('8248ef708b75727a',C,'stage_labs','Stabilize dehydration/electrolyte abnormalities and maintain NPO before pyloromyotomy; add potassium only with adequate urine output and an appropriate order.', 'Baseline dehydration and vomiting; stage_labs K 3.1 and alkalosis; neither supplies urine-output adequacy for keyed potassium-containing fluids.', 'stage_postop surgery/feeding outcome.', 'Labs support electrolyte correction, but potassium-safety prerequisites are missing from every prefix.', 'Either supply measured adequate urine output and a prescribed potassium fluid after resuscitation as authored context, or change the keyed initial-fluid option to isotonic resuscitation without premature potassium. Re-review options and rationale.',('rch-pyloric',))
add('9729bf71edce3119',C,'stage_postop','Resume postoperative feeds according to the specified surgical feeding order and the awake infant’s tolerance.', 'stage_postop supplies stable awake infant after surgery, but no feeding regimen; key requires clear liquids.', 'No later stage.', 'Postoperative status is necessary but does not establish a universal clear-liquid-first schedule.', 'Provide a specific prescribed feeding progression if retaining the current key; revise unsupported universal 12–24-hour/clear-liquid/dilution claims. Alternatively rewrite to tolerance-based prescribed breastmilk/formula feeding with independent review.',('chop-pyloric',))
add('b8f6c34736ed2d5d',C,'baseline','Classify supplied physiologic trends as improvement or findings that still warrant active follow-up, including the positive line culture.', 'Each matrix row supplies the trend; first row mixes unlabelled Celsius values with Fahrenheit; case has matched Fahrenheit/Celsius measurements.', 'All stages, especially stage_3 improvement narrative, repeat the row interpretations.', 'Self-contained rows support baseline after unit repair; a later chart is not necessary to classify a fully stated trend.', 'Make each temperature Fahrenheit first with Celsius parentheses using the existing matched chart values. Clarify single-choice columns as best trajectory interpretation so improvement does not deny continued monitoring.',('idsa-fever',))
add('7f1db592e0bf40fd',C,'baseline','Teach the patient to report the oncology plan’s fever threshold and infection symptoms promptly after chemotherapy.', 'Baseline oncology instructions and q6 supplied warning options; current 101 °F (38.3 °C) conflicts with 100.9 °F (38.3 °C).', 'stage_1 treatment, stage_2 culture and stage_3 recovery are unnecessary to prospective fever teaching.', 'The intended safety threshold is already baseline, but the numeric inconsistency needs repair before boundary approval.', 'Preserve the published ASCO/IDSA101°F(38.3°C) threshold already pinned in scripts/audit/temperature-prose-residual-adjudication.ts. Propose correcting the conflicting summary100.9°F threshold to the same sourced101°F pairing in both languages; do not arithmetically rewrite the source-pinned order/key. Independent review must approve the exact action threshold.',('idsa-fever',))
add('c9ddb715599fbf07',C,'stage_1','Identify assessed caregiver learning needs from the stated unsafe practices, without inventing the source of advice or inferring intent.', 'stage_1 reports unsafe practices and warm engagement; informal advice/neighbor/online videos claimed in the keyed explanation are not established there.', 'stage_2 emotional history and stage_3 teach-back outcomes.', 'The actual practices begin at stage_1; later sympathy does not prove the current rationale’s unsupported causal history.', 'Remove unsupported neighbor/online advice claims and conclusions that warmth excludes neglect; align the key/rationale to demonstrated learning needs, or explicitly author the required history at stage_1 for review.')
add('bb9ff3ab3ff079ec',A,'stage_2','Respond to the caregiver’s distress without judgment, address immediate medication danger, and connect her with practical support/resources.', 'stage_2 directly supplies tearfulness, lack of prior guidance/support, diphenhydramine suggestion and medication error concern; baseline infant assessment and stage_1 hazards.', 'stage_3 teach-back and planned home changes.', 'The individualized response requires the newly disclosed distress/support and medication context; the stage reports the problem, while the later stage reports the teaching outcome.',sources=('poison-help',))
add('68e5df7960d1bb86',C,'baseline','Distinguish correct teach-back, unsafe practices needing reteaching, and explicit access barriers requiring resources.', 'Matrix rows are self-contained except the gate/lock statement only says try this weekend; it does not establish inability to obtain equipment.', 'stage_3 repeats the same ambiguous quote; later visibility cannot establish an absent resource barrier.', 'Baseline is defensible only once the row itself supplies the determinant for its resource key.', 'Revise the gate/lock matrix row and matching stage_3 quote to an explicit affordability/transport barrier with requested equipment help and an interim protection plan; update bilingual rationale. This is proposed fiction requiring review, not recovered history.')
add('c827f2ece4ba697c',C,'baseline','Classify hypothetical pediatric dehydration findings into oral-rehydration teaching versus urgent evaluation using discriminating red flags.', 'Matrix supplies each hypothetical cue; isolated no-tears is currently keyed urgent, although it does not alone establish severe dehydration.', 'stage_1 actual assessment, stage_2 teaching and stage_3 improvement are not necessary for hypothetical cue classification.', 'No stage repairs a nondiscriminating row; baseline is sufficient after the row is made clinically discriminating.', 'Explicitly frame rows as possible findings. Replace isolated absent tears with a sourced composite including lethargy/poor perfusion, or rekey with full review; do not invent those findings in the current child’s chart.',('nice-dehydration',))
add('74147c736cbdfe8d',C,'stage_2_teaching','Recognize the patient’s unsafe self-adjustment of prescribed oxygen and teach use of the prescribed rate plus seeking help for symptoms.', 'The unsafe patient quote occurs at stage_2_teaching; stage_1_home describes adherence to 2 L; stem incorrectly points to Stage 1.', 'stage_3_equipment maintenance and subsequent outcome.', 'Stage_2 supplies the actual misconception, without an anchor solving the contradictory stage reference.', 'Change both stem languages from Stage 1 to Stage 2, then propose stage_2_teaching; preserve the existing prescribed oxygen value and verify related rationale against that local plan.')
add('545d112ac11f8548',R,None,'Give a thionamide before iodine in thyroid storm without inventing a total order for therapies that can start concurrently.', 'stage_0830 orders hydrocortisone STAT; ordered key places it after iodine despite rationale permitting concurrent steroid treatment.', 'stage_1200 completed drug sequence and improved vitals.', 'The necessary partial-order rule cannot justify a uniquely scored total order across all four actions.', 'Replace the embedded ordered-response construct with a focused thionamide-before-iodine question, preserving the parent and ID via reviewed replacement. Do not delay STAT steroid to make the old key fit.',('endotext-storm',))
add('cc1132738316b540',C,'stage2','Recognize unsafe oral resin administration in the lethargic patient and query the route while executing time-critical hyperkalemia orders safely.', 'stage2 supplies worsening ECG/K, lethargy, nausea and actual orders; present vomiting is asserted by q4 but not documented (vomiting occurred before admission).', 'stage3 stabilization and retrospective management summary.', 'Stage2 is the first actual drug/order context, but cannot prove present vomiting.', 'Remove unsupported current-vomiting assertions from stem/rationale and matching parent prose; frame the concern around actual alertness and ability to swallow safely, with clinician review of route/urgency and resin appropriateness.',('sps-label','ukka-hyperk'))
add('0f5aac8326dc6ee2',C,'stage2','Apply monitoring, administration and escalation safeguards to the newly prescribed emergency hyperkalemia therapies.', 'stage2 actual calcium/insulin-dextrose and other orders plus ECG instability; q5 rationale inherits the unsupported current-vomiting claim.', 'stage3 improved rhythm, potassium and perfusion.', 'The ordered medications are not available earlier; their desired effects are later. Content repair remains needed even if stage2 is the likely boundary.', 'Correct current-vomiting claims consistently with q4 and parent rationale; independently check each selected safeguard against the stage2 order set and current source guidance.',('sps-label','ukka-hyperk'))
add('73df80f9cc831a0e',C,'baseline','Recognize improving trends while continuing surveillance during unresolved AKI/hyperkalemia.', 'Matrix explicitly supplies trends. Multiple-per-row key marks both improvement/monitoring for four rows but only improvement for BP/HR and orientation.', 'stage3 narrative repeats those improvements; no later chart eliminates ongoing monitoring needs.', 'Baseline can support row interpretation; it cannot justify the inconsistent monitoring key.', 'Add ongoing-monitoring selections for BP/HR and orientation with matching rationale, or redesign mutually exclusive trajectory columns. Require independent key review for the chosen repair.',('kdigo-aki',))
add('802896cb6a9c1b8e',C,'stage_1','Recognize likely sepsis/systemic infection with worsening hypotension after fluid, rather than attributing the whole febrile neutropenic deterioration to a local line lesion.', 'stage_1 supplies post-bolus hypotension, rising lactate and oliguria; baseline neutropenic fever and PICC changes.', 'stage_2 cultures/antibiotic escalation and stage_3 confirmation/source control.', 'Actual post-bolus deterioration first exists at stage_1; its raw findings do not require showing later confirmation. Rationale overstates exclusion of dehydration.', 'Revise opt_B rationale and strategy: severe dehydration can cause hypotension and elevated lactate; the combined fever/neutropenia/line findings require urgent sepsis evaluation, not a categorical physiologic impossibility.',('sepsis-guideline',))
add('a0e42e1a6716455d',R,None,'Escalate concerning preliminary line culture, ensure prompt antimicrobial therapy, and coordinate safe source control/essential infusion access.', 'stage_2 includes preliminary results and new vancomycin order; current total-order key assumes report-before-verification and mandates source control last.', 'stage_3 confirmed CRBSI, removal and replacement/access outcome.', 'Concurrent verification, escalation and access planning cannot be uniquely ordered from this chart; earlier visibility omits the drug order while later visibility supplies outcomes.', 'Replace ordered-response with SATA or another natural format assessing safe coordination without arbitrary ranking. Correct >2-hour versus at-least-2-hour diagnostic wording consistently; do not mandate unnecessary source-control delay for new central placement.',('idsa-crbsi','sepsis-guideline'))
add('664554d731c00372',C,'baseline','Tolerating spit-out mouth rinses does not demonstrate readiness to replace prescribed nutrition with oral intake.', 'q6 stem explicitly supplies rinse tolerance and inability to swallow; baseline severe oral/esophageal mucositis and existing PN.', 'stage_3 line replacement/clinical improvement does not determine whether a tube-feeding route is possible.', 'Self-contained oral-capability data support baseline, but inability to swallow does not make all enteral tube feeding impossible.', 'Narrow stem/options/rationale from enteral nutrition generally to resuming oral nutrition and stopping PN on rinse tolerance alone; remove blanket tube-enteral impossibility and have the team reassess the feeding route.',('nice-nutrition',))

add('ee56ac60cc709ab2',H,None,'Implement the prescribed peripheral potassium safely, including the actually ordered magnesium and ED-required monitoring.', 'Baseline establishes low magnesium and potassium; q4 supplies the potassium prescription; stage_2_ed_initial alone supplies the magnesium order and ED telemetry/pump protocol.', 'stage_3_six_hours_ed response; stage_2 also explicitly lists several keyed safety actions.', 'Baseline cannot prove an existing magnesium order from hypomagnesemia alone. Stage_2 is complete but substantially supplies the tested protocol actions. Whether this is legitimate order-implementation reasoning or answer retrieval needs construct adjudication.', 'Independent reviewer should choose a revised self-contained administration stem or approve stage_2 as a protocol-application construct with an explicit rationale. Do not resolve by calling all potassium monitoring universally identical.',('kcl-label',))
add('4170e57ae9a4c3ec',A,'stage_lead_labs','Manage an asymptomatic toddler’s confirmed venous BLL 18 with exposure education and early repeat venous testing rather than emergency chelation or no follow-up.', 'Baseline asymptomatic child/exposure history; stage_lead_labs identifies the specimen as venous; q2 supplies 18.', 'stage_lead_education describes the subsequent education plan.', 'Specimen type determines confirmation versus follow-up timing; an untyped screening value in the stem is insufficient. The lab stage gives the result/reference value but not the selected 1–3-month follow-up plan.',sources=('cdc-lead',))
add('47e8dfe5f72a69a4',A,'baseline','Interpret explicitly decreased stool/bilirubin and fading rash as disease-response directions, while monitoring glucose and infection risk under the named immunosuppressants.', 'q6 stem names treatment and duration; every row supplies its finding and, where needed, direction of change; baseline supplies transplant/GVHD context.', 'stage_3 labels the course improved; stage_2 deterioration values are not required to calculate a trend already expressly stated in the rows.', 'The row says decreased, not compare this isolated number to admission. Extrapolating one baseline eight-hour stool output to a full day is not warranted. Absence of fever under immunosuppression needs vigilance without a prior fever.',sources=('ruxolitinib-label',))
add('f9808a51e6bb06d4',C,'stage2','Use the current postpartum clinical and laboratory pattern to identify severe-feature preeclampsia and explain why the HELLP triad is not demonstrated.', 'stage1 current BP/CNS findings and stage2 current platelet/AST/ALT/LDH results; delivery-admission baseline labs are several days old.', 'stage3 treatment response; baseline case title currently spells out the diagnosis blank.', 'Current lab exclusion requires stage2 even though options suggest the pattern. A boundary alone cannot hide the always-visible diagnostic title.', 'Neutralize the bilingual parent title to a presenting-symptom title before proposing stage2. Preserve actual clinical data and independent review of all three dropdown keys; survey sibling impact of the shared-title change.',('acog-preeclampsia',))
add('5e6cd8254c891c72',A,'stage_2','Before the caregiver leaves, address the real wandering/fire hazards, orient temporary supervision, and notify the provider about disclosed diphenhydramine use.', 'Baseline noon departure/neighbor and unsafe home; stage_1 actual burner event; stage_2 actual three-week diphenhydramine exposure with more confusion.', 'stage_3 completed medication discontinuation, alarms and community follow-through.', 'The selected bundled plan addresses an actual medication exposure not asserted in the stem. A proposed action naming that drug is not evidence it has been used; stage_2 supplies the missing determinant without performing the plan.',sources=('nia-dementia-safety',))
add('d92f499014ea0870',A,'stage_2','Build a cue-specific safety/support plan covering wandering, stove, falls, chemicals, uncertain medication ingestion and caregiver capacity.', 'Baseline environmental/functional hazards; stage_1 unsafe stove behavior; stage_2 crushed tablets, uncertain intake, missed doses and diphenhydramine.', 'stage_3 pharmacy formulations, provider discontinuation and implemented safety measures.', 'The medication/formulation component requires the private disclosure. stage_2 contains problems and history rather than completed referrals or the keyed plan.',sources=('nia-dementia-safety',))
add('3db55ace83b191ac',C,'stage_2','Interpret the actual febrile ANC 980 and new cardiac biomarker/exam cluster as concurrent neutropenia with infection risk and suspected myocarditis.', 'stage_2 actual fever, ANC decline, chest symptoms, troponin/CRP/BNP and heart-failure findings; baseline comparators.', 'stage_3 echo confirmation; always-visible title currently names both diagnoses.', 'The stem asks what the actual Stage 2 findings support, not merely what hypothetical combinations mean. stage_2 supplies them, but the title pre-answers the diagnostic construct.', 'Neutralize bilingual parent title to clozapine initiation with an acute change; preserve stage_2 raw findings. Review sibling impact of shared-title repair.',('clozapine-label',))
add('e091c2e5e7c356f8',A,'stage_2','Recognize that current fever/neutropenia and suspected myocarditis activate the supplied facility hold-and-notify policy.', 'Baseline gives conditional policy; stage_2 first supplies actual policy-triggering fever, ANC and cardiac findings.', 'stage_3 records the hold and notification already performed.', 'Knowing a conditional policy does not establish its trigger at a normal baseline. stage_2 supplies the abnormal assessment, not the later hold/notification; naming a toxicity in the title cannot replace timing-specific assessment.',sources=('clozapine-label',))
add('53abf6daaaf8fd16',A,'stage_2','After hold/notification, anticipate both urgent infection evaluation/treatment and cardiac monitoring/workup appropriate to this client’s concurrent findings.', 'Stem supplies hold/notification; stage_2 supplies febrile neutropenia and cardiac injury; baseline supplies policy.', 'stage_3 culture/antibiotic execution, echo diagnosis and follow-up plan.', 'A hold could have one of several causes; the combined infection and cardiac pathways require stage_2 evidence. Initiated precautions in stage_2 do not supply the remaining diagnostic/treatment bundle.',sources=('clozapine-label','idsa-fever'))
add('05e76aac6f75e2cb',C,'stage_3','Distinguish partial improvement in supported vital signs from unresolved toxicity, and identify appropriate recovery trends and escalation triggers.', 'stage_2 initial biomarkers; stage_3 repeat ANC/troponin/CRP, symptoms, oxygen-supported vitals and echo; hypothetical options B/C/E state future indicators.', 'No later stage. Stage_3 gives measurements, not a claim that toxicity resolved.', 'Actual-state option A needs current trajectory, unlike hypothetical recovery options. Its absolute not-yet-improving wording conflicts with acknowledged partial clinical improvement.', 'Revise option A in both languages to relatively stable with toxicities not yet resolved rather than not yet improving, and align rationale; retain stage_3 for actual trajectory evaluation.',('clozapine-label',))
add('816f8ee32a25b1ca',A,'stage_1','Classify actual unauthorized curiosity access/photo creation, requests requiring verification, and overheard communication without safeguards.', 'Baseline contact/policy; stage_1 establishes no care role, absent photo consent with visible wristband, employer request and visitor earshot.', 'stage_2 mitigation and stage_3 formal breach determination.', 'Abbreviated matrix labels alone omit consent and safeguarding facts. The stage provides event facts, not final legal breach adjudication or the completed response.',sources=('hhs-incidental','hhs-workers-comp','hipaa-family'))
add('081b3b885639d73b',H,None,'Contain the actual privacy exposures, route requests/reporting correctly, and handle the personal-device image under an authorized incident-response process.', 'stage_1 event details and baseline reporting policy establish most actions; option D mandates irreversible local/recently-deleted image removal before Privacy Officer review.', 'stage_2 performs the keyed deletion/other containment and stage_3 reviews cloud transmission.', 'stage_1 is the likely event boundary, but no supplied policy establishes evidence-preserving authority for immediate permanent deletion. Later performance is not proof that the action is sound.', 'Obtain a specific approved institutional photo-incident procedure or revise D and matching stage/rationale to contain sharing and follow Privacy Officer/security direction while preserving required incident evidence. Do not present HIPAA as universally mandating immediate permanent deletion.',('hhs-breach',))

add('1e12ffbae816c10e',A,'stage_1','Teach contact precautions nonjudgmentally, acknowledge the daughter’s reported lack of orientation, and verify gown/glove/hand-hygiene performance.', 'Baseline MRSA/draining wound and local visitor policy; stage_1 daughter’s unprotected repositioning and explicit nobody-told-me report.', 'stage_3 successful return demonstration; stage_2 unrelated breaches.', 'The acknowledgment option asserts a particular teaching gap, not merely a universal need for orientation. stage_1 supplies that gap without showing subsequent successful teaching.',sources=('cdc-contact',))
add('f56f69400453dee6',C,'stage_2','Prioritize a symptomatic BP 186/102 and missed monitoring that cross the actual provider call parameter over interpersonal mediation.', 'q3 supplies BP/headache/missed check; stage_2 supplies the hospitalist SBP >180 call rule.', 'stage_3 call, medication and response; stage_2 last sentence currently tells the learner Marcus has verified the threshold is crossed.', 'The numerical call rule is necessary to establish the full keyed proposition, but the completed interpretation must be removed from the same prefix.', 'Remove the bilingual stage_2 sentence that pre-interprets the threshold; retain measured BP, symptom and verbatim local order. Also correct the accompanying ECG description of HR 92 as sinus tachycardia after clinical review.',('aha-tachycardia',))
add('b1d86a48db7dac8f',C,'stage_2','Address the active symptomatic care gap now, then conduct private behavior-focused feedback/coaching and appropriate safety/conduct reporting.', 'stage_1 observed handoff and conduct; stage_2 current BP, headache, missed check and call parameter.', 'stage_3 executes the whole proposed response; stage_2 pre-interprets the call threshold.', 'Baseline is stable and cannot establish urgency now. stage_2 raw findings suffice once the interpretation sentence is removed.', 'Apply the shared stage_2 interpretation/ECG corrections specified for q3; preserve q4 actions and require joint parent review.',('aha-tachycardia',))
add('a8982658716e5dd4',C,'stage_2','Ensure prompt hospitalist notification through the primary nurse using the current symptomatic BP and stated call parameter before paperwork or conduct follow-up.', 'stage_2 actual BP/headache/missed monitoring and hospitalist order; baseline absence of PRN antihypertensive.', 'stage_3 Marcus explicitly directs the selected action; stage_2 currently confirms threshold crossing.', 'An answer option naming current BP does not supply its value or actual trigger. stage_2 is needed, with its answer-supplying interpretation removed.', 'Apply shared stage_2 interpretation/ECG corrections; retain current role-specific q5 options pending independent review.',('aha-tachycardia',))
add('dcf2dbbe0f27ca65',C,'stage_1','Recognize acute relapse vulnerability from pain, fear and withdrawal from supports, while exploring ambiguous self-harm language rather than assigning a legal hold from one sentence.', 'Baseline OUD/pain and absence of objective withdrawal; stage_1 improved vitals, isolation, catastrophic relapse statement and denial of hurting himself.', 'stage_2 interpersonal crisis and stage_3 explicit craving/logistical barriers.', 'The actual support withdrawal/clarification are stage_1 additions. The rationale overstates the documented assessment as a formal denial of both intent and plan.', 'Replace unsupported intent-and-plan-denied assertions with the exact documented denial and the need for a complete continuing safety assessment; do not imply that denial alone rules out a crisis or governs involuntary-hold law.',('samhsa-safe-t',))
add('18d46f73fa754220',A,'stage_2','Prioritize worsening hopelessness/isolation and safety reassessment after the MAT prescriber has already been contacted, while protecting confidentiality.', 'stage_2 privately supplied collateral, client distress, and documented provider contact resolving the previously open MAT question.', 'stage_3 worsening pain, craving and discharge barriers.', 'Earlier records still have an unresolved MAT plan, making distractor D potentially appropriate. stage_2 supplies its resolution and the new psychosocial priority without assigning the nursing response.',sources=('samhsa-safe-t','hipaa-family'))
add('b02619cc0abe50fd',A,'stage_2','Reflect distress, explore meaning and safety, offer support contact, and obtain permission for partner participation without deploying private collateral as confrontation.', 'Stem quotes distress; stage_2 establishes Tanya’s private hallway report and the client’s mistrust/isolation; baseline identifies supports.', 'stage_3 later craving and discharge planning.', 'The quoted feeling is self-contained, but the rejection of the private-collateral option requires its actual conversational context; stage_2 provides it without the nurse’s selected response.',sources=('samhsa-safe-t','hipaa-family'))
add('73a1a25cd88535fd',C,'stage_3','Respond to disclosed craving, reinforce a reconciled prescribed pain/OUD regimen, activate support/follow-up/transportation and review naloxone readiness.', 'stage_3 explicit craving, wearing-off block, sponsor/transport/appointment gaps and kit question; stage_2 analgesic/OUD orders.', 'No later stage; discharge readiness data are the input, not a completed safe-discharge outcome.', 'Earlier stages lack the full individualized barriers. However, baseline says the daily buprenorphine dose was already taken this morning, while stage_2 orders the full daily dose again tonight and stage_3 records it given.', 'Reconcile actual daily buprenorphine timing with prescriber/source review across baseline and stages2/3 before reinforcing the plan; do not silently endorse a second full same-day dose. Clarify authorized timing or next scheduled dose, and obtain client permission for shared teaching.',('buprenorphine-label','samhsa-overdose'))
add('0eb41edc4fe6849b',A,'stage_2','Facilitate safe assisted toileting for current urgency after Foley removal while addressing pain and orthostatic fall risk, using the retention pathway if unsuccessful.', 'stage_2 Foley removal, urgency, bladder scan 420 and symptomatic failed standing; baseline hip precautions and pain risk.', 'stage_3 successful commode voids and improved orthostasis.', 'At baseline the Foley remains in place. The frozen checker rationale discusses respiratory-sedation prioritization rather than this actual toileting question and cannot govern. stage_2 gives the relevant current need without showing the successful intervention.',sources=('cdc-cauti',))
add('375aacb3f6469581',C,'stage_2','Integrate pain-enabled mobility, orthostatic precautions, nutrition, moisture/offloading and prompted toileting around actual current needs.', 'Baseline skin/intake/pain; stage_1 supportive measures; stage_2 Foley removal, urgency and orthostatic failure.', 'stage_3 successful transfers and new device injury.', 'The urgency-driven voiding component first arises at stage_2. The option also assumes hearing aids and ordered ice not established anywhere in the current record.', 'Remove the unsupported hearing-aid/ordered-ice specifics from option A and matching rationale, or explicitly establish their indication/order as reviewed fictional context. Preserve reassessment of sedation and orthostasis before activity.',('pressure-guideline',))
add('2e075b7d68f40f7b',A,'stage_3','Recognize intact nonblanchable heel erythema at the shifted boot strap as a new device-related Stage1 injury and remove the pressure source, assess/document/offload and notify per protocol.', 'stage_3 supplies intact skin, warmth, size, location and shifted strap mechanism; stem only says new nonblanchable redness.', 'No later stage. Other stage_3 improvements are not determinants of the heel response.', 'Earlier heels were intact without the lesion; redness alone cannot establish the complete device-related staging proposition. stage_3 supplies raw appearance and mechanical history rather than the corrective action.',sources=('pressure-guideline',))
add('3547d5f076446b1e',C,'stage_1','Connect the new simultaneous phosphate/potassium/magnesium decline after PN with refeeding physiology, while treating glucose as a concurrent concern.', 'Baseline prolonged poor intake and PN risk; stage_1 actual electrolyte declines and glucose rise with a benign site.', 'stage_2 severe organ dysfunction and stage_3 response; the always-visible title presently names refeeding syndrome as already occurring.', 'A risk label at baseline does not establish the realized post-PN pattern. stage_1 gives measurements; the diagnostic title must first stop supplying the diagnosis blank.', 'Neutralize bilingual parent title to nutrition initiation after prolonged poor intake; retain the legitimate high-risk assessment in baseline and review sibling effects.',('aspen-refeeding','nice-nutrition'))
add('e7820c89234bfb5d',C,'stage_2','Prioritize active dysrhythmia/respiratory compromise with severe electrolyte decline while concurrently escalating possible catheter infection.', 'stage_2 actual low phosphate/K/Mg, PVCs/QT, shallow breathing, altered mentation and purulent site; earlier phases lack this competing acute cluster.', 'stage_3 ordered treatment and improvement.', 'Stage_2 establishes current organ compromise without stating the answer, but rationale categorically excludes infection as a contributor to rhythm/respiratory findings.', 'Soften causal certainty in correct/choice rationale: electrolyte decline strongly supports urgent correction; infection may coexist or contribute and needs timely parallel evaluation. Correct impossible shared PICC timeline: stage_2 at30h claims dressing changed24h earlier although line was placed at18h.',('aspen-refeeding','sepsis-guideline'))
add('0620f6656c0e487d',C,'stage_2','Escalate persistent electrolyte decline with organ effects and new drainage; anticipate supervised nutrition adjustment/repletion and prompt paired cultures with antimicrobial treatment.', 'stage_2 failed prior repletion, current thresholds and new PICC drainage; baseline replacement protocol.', 'stage_3 actual reduced-rate/antibiotic orders and response.', 'Baseline protocol alone cannot establish current thresholds or a new infection. stage_2 provides indications but the shared line timeline is internally impossible.', 'Correct stage_2 PICC dressing timing using an explicitly reviewed chronology; clarify culture-before-antibiotic wording as conditional on prompt collection without material treatment delay. Avoid a universal prohibition on prescribed PN cessation in life-threatening refeeding.',('aspen-refeeding','sepsis-guideline','idsa-crbsi'))
add('c8306bb54be5fce7',C,'stage_2','Distinguish immediate nutrition/electrolyte actions from timely culture/antibiotic coordination and ongoing glucose support in the current crisis.', 'Stem supplies received orders and matrix names actions; stage_2 establishes actual dysrhythmia/respiratory urgency relative to infection workup.', 'stage_3 repeats orders and reports their outcome.', 'No need to wait for stage_3 order transcription, but baseline has no active organ compromise. Current columns make cultures an unconditional prerequisite despite byChoice allowing a prompt-collection exception.', 'Revise culture/antibiotic timing columns and rationale to preserve prompt treatment if cultures cannot be obtained without significant delay; correct shared stage_2 line chronology. Review selection-mode uniqueness after wording repair.',('sepsis-guideline','idsa-crbsi'))

add('b87b748b0a8fe610',A,'stage_2','Identify the actual acute transfusion reaction from the new overload-sign cluster, not merely the patient’s pre-existing susceptibility.', 'Baseline chronic heart/kidney disease and mild unchanged crackles; stage_1 remains stable; stage_2 new hypertension, hypoxemia, S3, JVD, spreading crackles, edema and low urine output.', 'stage_3 BNP/imaging and diuretic response; stage_4 explicit TACO diagnosis and resolution.', 'The four evidence alternatives describe different possible clusters. Risk factors do not establish which occurred. stage_2 reports the actual discriminatory findings without naming the selected diagnosis; the title names both competing reactions.',sources=('taco',))
add('5042b7fcf52e7d99',C,'stage_2_after_dose','Respond to current opioid-associated sedation/respiratory compromise with immediate airway assessment/support, cessation of further opioid, help and indicated oxygen/reversal, then documentation.', 'stage_2_after_dose supplies RR10, SpO2 90%, repeated stimulation and score3; baseline/stage_1 are stable.', 'stage_3_stabilized records the performed actions and recovery.', 'The current emergency first occurs at stage_2, but its unique A-B-C-D-E ordering is not established: calling for assistance, oxygen and escalation overlap, and preparing naloxone need not await oxygen attachment.', 'Replace the strict total ordering with an initial-response set plus post-stabilization documentation, or a narrower sourced dependency. Correct stage_2 structured-measurement column label from0900 to0930 to match observation time. Review the case’s 15-minute protocol versus recorded30-minute reassessment; do not portray the interval as compliant without explanation.',('aha-opioid','morphine-label'))
add('1f137477204f33f1',C,'stage_2_teachback','Compare the spouse’s peroxide/tight-packing teach-back with the ordered saline/dressing method and identify the need for coached reteaching.', 'Baseline actual dressing orders; stage_2_teachback quotes the incorrect method. Global stem and summary currently label teach-back failed/unsafe before the learner sees it.', 'stage_3_followup gives the reteaching sequence and successful return demonstration.', 'stage_2 is the earliest actual teach-back evidence; global answer labels must be removed before the boundary tests interpretation rather than recognition of the label.', 'Neutralize bilingual parent stem and summary to describe a home wound-care teaching visit without announcing failure or unsafe understanding. Preserve quoted stage_2 response and prescribed method; review sibling effects.',('ahrq-teachback',))
add('4a1fb7e61c0936a2',A,'stage_2_assessment','Report the combined concern for intracranial injury and hip fracture following the completed fall assessment, maintaining movement precautions pending evaluation.', 'Baseline anticoagulant and prior orientation; stage_1 unwitnessed fall/hip pain; stage_2 new disorientation, vomiting, unequal pupils and shortened externally rotated leg.', 'stage_3 retrospective environmental/medication prevention review.', 'stage_1 warrants evaluation and precautions, but the part refers to the completed fall assessment and its rationale specifically prioritizes new neurologic changes together with fracture findings. stage_2 establishes that combined actual finding set without naming the diagnosis or directing treatment. This semantic distinction needs independent adjudication; distractor elimination alone is not evidence of the completed assessment.',sources=('nice-head-injury','hip-fracture'))
add('921c126c050de4ee',C,'stage_1','Infer pump-failure shock from new hypotension and diffuse congestion in AMI and anticipate clinician-directed circulatory support.', 'Baseline ECG establishes anterior infarction; only stage_1 supplies BP80/50, HR110 and diffuse crackles. Always-visible title currently names cardiogenic shock.', 'No later stage; hide the diagnostic answer presently supplied in the global title.', 'stage_1 raw deterioration data are required, but no existing anchor can suppress the global answer label.', 'Neutralize the bilingual title; review the categorical immediate-inotropic-support wording against current shock guidance, supplying a specific prescribed support plan or broader hemodynamic-support choice if needed. Preserve urgent reperfusion framing and avoid suggesting inotropes alone are definitive.',('acc-shock',))
add('b922586401896706',R,None,'Recognize confirmed pulseless VF and prioritize CPR/early defibrillation with minimal interruptions and correctly timed medication during ongoing resuscitation.', 'Stem gives unresponsiveness/chaotic rhythm; stage_1415 supplies absent carotid pulse and waveform; no device-availability or staffing context makes every listed preparatory action uniquely sequential.', 'No later stage. Parent title supplies broad arrest context but is not a pulse assessment.', 'Anchoring to stage_1415 repairs missing pulse evidence, not the sequence ambiguity: preparing epinephrine can occur concurrently, and rationale implies administration after the first shock without qualifying the shockable-rhythm algorithm.', 'Replace the total-order part in place with a narrower current-algorithm decision, such as immediate CPR resumption after shock, or explicitly bounded steps with justified dependencies. Include confirmed pulse assessment in the new stimulus. Independently review all epinephrine timing/dose language; preserve identity/parent pending replacement approval.',('aha-arrest',))
add('74b943503fa2ab41',C,'stage_1','Apply the chart’s explicit INR>1.7 exclusion rule to the current INR1.8 and support timely alternative reperfusion evaluation.', 'Stem supplies INR/CT/time/BP, but explicitly requires the institutional protocol; that protocol first appears in stage_1 together with the neurologist’s already-completed eligibility conclusion.', 'stage_2 CTA/candidacy; stage_3 reperfusion/deterioration; stage_4 hemorrhage treatment. Also remove stage_1 application of the exact eligibility answer.', 'Baseline numbers alone do not supply the requested local rule; stage_1 presently provides both rule and answer, so anchor-only cannot meet the non-answer-revealing criterion.', 'Keep the institutional threshold as a rule in stage_1, remove the neurologist’s statement that this patient is excluded because of INR and the already-selected next step from the decision-time exhibit; preserve chronology through a reviewed chart reorganization. Alternatively move only the governing protocol to baseline and re-review baseline boundary.',('alteplase-label',))
add('b99d09e91cc81278',C,'stage_2','Prepare this thrombectomy candidate under the specific IV BP-control order, swallowing precautions, access/monitoring requirements and a valid decision-specific consent determination.', 'stage_2 contains the nicardipine order and wife’s documented authorization; baseline aphasia does not establish incapacity. Current stage_2 equates aphasia with inability to consent and narrates completed preparation.', 'stage_2 post-titration BP and completed-preparation statements supply actions being selected; stages_3/4 have different postprocedure BP goals and outcomes.', 'Earlier prefixes lack the actual prescribed agent and decision-specific capacity facts; stage_2 requires substantive revision to avoid aphasia=incapacity and completed-answer disclosure.', 'Specify an assessed inability to make this urgent decision despite supported communication, with the authorized proxy’s role; revise optionD and both rationales to match. Separate preprocedure orders/assessment from completed titration/access/monitoring execution, keeping only needed decision inputs visible. Review shared-stage effects.',('aphasia-capacity','nicardipine-label'))

add('05bb74f900e8b04e',C,'stage2','Choose removal, protocol mitigation or monitored retention according to each object’s risk and the patient-specific safety assessment while preserving necessary care.', 'Rows name hazards/needed equipment; stage1 establishes high acute risk; stage2 supplies continuous-observation order and the assessed suitability of retaining pole/table, but also spells out the completed sweep.', 'stage2 item-by-item completed removal/modification/retention gives the matrix answers; stage3 later calm behavior and consultation do not determine the sweep.', 'Baseline identifies several hazards but does not establish the full conditional retention assessment. stage2 needs its completed-answer list separated from pre-sweep constraints.', 'Retain required-care/observation and contextual equipment-risk facts in a decision-time exhibit; move or remove the completed disposition of each listed item from that boundary. Make any equipment modification conditional on approved clinical/device policy, not improvised shortening. Re-review all affected siblings, including agitation during the sweep.',('jointcommission-suicide',))
add('7b93b19069276111',A,'stage3','Respond to new burning and vein redness during peripheral potassium infusion by stopping and assessing the site, maintaining safe access and escalating.', 'stage3 is the first actual site complaint/redness while infusion is running; earlier stages describe the indication and revised order, not a site complication.', 'No later stage. stage3 reports partial electrolyte improvement but does not perform the selected site-safety action.', 'The response alternatives do not establish that a new infusion-site complication occurred. stage3 supplies that new determinant; prior medication risk alone cannot select the next action for the present assessment.',sources=('kcl-label',))
add('8b3faa785726d8b1',A,'stage_1_0900_1100','Communicate the actual0700–1100 deterioration and possible bleeding in an urgent SBAR, requesting current bedside evaluation rather than normalizing findings or waiting.', 'Baseline0700 comparison; stage_1_0900_1100 supplies worsening vitals, confusion, urine decline, sanguineous drainage and expanding stain.', 'stage_2_1115_1200 explicitly lists the prepared SBAR, records the call and refusal, and gives1200 labs; stage_3 confirms hemorrhage.', 'This is preparation for the first call, so the Stage2 task label does not require reading the later call transcript. stage_1 supplies every requested trend without the already-composed SBAR; baseline alone does not establish deterioration.',sources=('ahrq-sbar',))
add('8fdddc13883a4a38',A,'stage_1_consent_concern','Recognize that proceeding on the signed form is inappropriate because understanding of risks and voluntariness are not established by the patient’s stated experience.', 'Global summary reports no risk understanding; stage_1 adds that she signed because the doctor seemed to want her to, establishing the pressure component of the selected compound answer.', 'stage_2 hold/interpreter/provider escalation and stage_3 corrected consent outcome.', 'Language background or an absent interpreter notation cannot alone prove invalid consent or pressure. stage_1 provides the actual expressed comprehension/voluntariness concerns without labeling the selected conclusion.',sources=('ama-consent','hhs-language'))
add('b174c7627b0e9957',C,'opus_icit_stage_1','Consider ICI-associated myocarditis with possible concurrent immune hepatitis from the new ECG/conduction findings plus cardiac and liver injury markers, while evaluating alternatives.', 'Baseline symptoms and biomarker abnormalities; opus_icit_stage_1 new diffuse ST changes and PR prolongation. Global title already states myocarditis with hepatotoxicity.', 'opus_icit_stage_2 specialist diagnosis/LVEF decline; stage3 response. Also remove global diagnostic answer.', 'The requested Stage1 constellation includes new conduction/ECG findings absent earlier; neither a diagnostic title nor liver-enzyme elevation alone establishes the combined etiology.', 'Neutralize bilingual title. Qualify hepatic attribution and viral exclusion in rationale: known hepatic metastases and other causes require assessment; present immune-mediated hepatitis as a leading suspicion, not proved by transaminases. Align option/rationale wording and preserve cardiology evaluation of ACS.',('sitc-ici',))
add('5b9a3f652e7815e8',C,'opus_icit_stage_2','Promptly implement ordered oxygen for93% below the case target, monitoring/access and urgent corticosteroids, with timely higher-acuity transfer coordination.', 'opus_icit_stage_2 first supplies93% room-air saturation, rest dyspnea, worsening cardiac findings and the specific treatment orders.', 'stage2 already-administered methylprednisolone and oxygen response; stage3 later therapeutic response.', 'stage2 supplies the required oxygen trigger/order; a boundary cannot prove the unique order of oxygen versus existing telemetry/access checks or require transfer preparation to await steroid delivery.', 'Replace the forced total order with justified prerequisites/concurrent actions; remove the completed administration/oxygen-response sentence from the decision-time exhibit. Correct Chinese step-down unit translation (currently implies lowering acuity despite escalation) and avoid calling steroids invariably definitive or corrective. Independent format/key review required.',('sitc-ici',))
add('818efa64297eb1f4',C,'stage_1','Prioritize the newly prescribed urgent IV dexamethasone regimen for progressive cord compression over routine assessment, catheter preparation or reassurance.', 'Baseline prior oral dexamethasone4mg/day and neurologic concern; stage_1 new IV bolus/order, MRI confirmation and additional deterioration; bladder scan420mL follows three hours without voiding.', 'stage_2 says bolus already given and reports further decline; stage_3 postoperative response.', 'The specific current prescription first exists at stage_1. An urgent order is legitimate care context, but q2 rationale incorrectly calls the420mL scan a post-void residual when no void occurred.', 'Correct q2 catheter-choice rationale in both languages from post-void residual to current bladder volume with inability to void, checking the matching sibling phrasing. Keep the immediate prescription as the case order; do not imply steroids should await MRI in general or guarantee prevention of further deficit.',('nice-mscc',))

def write():
    packets=[json.loads(p.read_text()) for p in sorted((ROOT/'phase-a/parents').glob('*.json'))]
    lookup={e['rowKey']:(p,e) for p in packets for e in p['frozenExceptions']}
    assert len({x['rowKey'] for x in ROWS})==len(ROWS)
    for x in ROWS:
        p,e=lookup[x['rowKey']]
        x.update(packetId=p['packetId'],bankPath=p['bankPath'],parentCaseId=p['parentCaseId'],partId=e['partId'],sourceParentSha256=p['currentParentSha256'])
        stages=[s['id'] for s in p['currentParent']['caseStudy']['stages']]
        b=x['proposedBoundary'];assert b in stages or b in ('baseline',None)
        x['stagesVisibleIfApproved']=[] if b=='baseline' else stages[:stages.index(b)+1] if b else None
        x['stagesHiddenIfApproved']=stages if b=='baseline' else stages[stages.index(b)+1:] if b else None
        x['boundaryConditionalOnContentReview']=x['disposition']!=A
    (ROOT/'phase-a/dispositions.json').write_text(json.dumps(ROWS,ensure_ascii=False,indent=2)+'\n')
    print(f'Wrote {len(ROWS)} fresh producer dispositions (not accepted).')
if __name__=='__main__':write()
